<script setup lang="ts">
import { artworkURL } from './artwork'
import { computed, ref, watch, onMounted } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { musicApi } from './core'
import type { Track, ExportData } from './core'
import { useMusic } from './stores/music'
import { useOverlay } from './stores/overlay'
import Icon from './ui/Icon.vue'
import TrackRows from './ui/TrackRows.vue'
import { loadDiscovery } from './discovery'
const music=useMusic(),overlay=useOverlay(),route=useRoute(),router=useRouter(),query=ref(''),results=ref<Track[]>([]),searching=ref(false),searched=ref(false),shared=ref<ExportData|null>(null)
const page=computed(()=>route.path.split('/')[1] || 'library'),selected=computed(()=>music.selected),p=music.player
const now=computed(()=>p.currentTrack),historyTracks=computed(()=>music.history.map(h=>h.track)),sharedTracks=computed(()=>shared.value?.playlists.flatMap(p=>p.tracks)||[])
const discovery=ref<Track[]>([]),discovering=ref(false),discoveryError=ref('')
async function discover(){if(discovering.value)return;discovering.value=true;discoveryError.value='';try{discovery.value=await loadDiscovery(musicApi,tracks=>discovery.value=tracks)}catch(e){discoveryError.value=e instanceof Error?e.message:String(e)}finally{discovering.value=false}}
async function loadPage(){shared.value=null;if((page.value==='library'||page.value==='search')&&!discovery.value.length)void discover();if(page.value==='history')await music.loadHistory();if(page.value==='shares')await music.loadShares();if(page.value==='share')await music.run(async()=>shared.value=await musicApi.shared(String(route.params.token)))}
onMounted(loadPage);watch(()=>route.path,loadPage)
async function search(){if(!query.value.trim())return;searching.value=true;await music.run(async()=>{results.value=await musicApi.search(query.value);searched.value=true});searching.value=false}
function play(tracks:Track[],index=0){if(tracks.length)music.run(()=>p.playTracks(tracks,index))}
function choose(id:string){music.selectedID=id;router.push('/library')}
function reorder(from:number,to:number){const current=selected.value;if(!current)return;const ids=current.tracks.map(t=>t.id);const item=ids.splice(from,1)[0];if(item){ids.splice(to,0,item);music.update(current,ids)}}
function removeTrack(index:number){if(selected.value)music.update(selected.value,selected.value.tracks.filter((_,i)=>i!==index).map(t=>t.id))}
async function rename(){if(!selected.value)return;const name=prompt('歌单的新名称',selected.value.name);if(name?.trim())await music.update(selected.value,selected.value.tracks.map(t=>t.id),name)}
function deletePlaylist(){if(selected.value&&confirm(`删除歌单「${selected.value.name}」？`))music.remove(selected.value)}
function scrollCollection(){document.querySelector('#collection')?.scrollIntoView({behavior:'smooth'})}
function shareName(id:string){return music.playlists.find(p=>p.id===id)?.name || '单曲分享'}
const heading=computed(()=>({likes:'把喜欢，留在身边。',history:'最近，循环了什么？',queue:'下一首，交给自己。'}[page.value as 'likes']||''))
</script>
<template>
 <template v-if="page==='share'"><section v-if="shared" class="share-view"><span class="eyebrow">SHARED WITH YOU / 只读分享</span><h1>{{shared.playlists[0]?.name || '分享的音乐'}}</h1><p class="lead">好音乐，值得与你分享。复制之后，就能在自己的空间编辑。</p><button class="primary" @click="music.run(async()=>{await musicApi.copyShare(String(route.params.token));await music.refresh();router.push('/library');music.notify('歌单已复制到你的空间')})"><Icon name="plus" :size="18"/>复制到我的歌单</button><TrackRows :tracks="sharedTracks" @play="play(sharedTracks,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></section><div v-else-if="!music.error" class="empty-state">正在打开分享…</div></template>
 <template v-else-if="page==='search'"><section class="page-heading"><span class="eyebrow">DISCOVER / 发现歌曲</span><h1>总有一首，正合心意。</h1><p class="lead">从歌曲、歌手或专辑开始，找到下一份喜欢。</p></section><form class="search-box" @submit.prevent="search"><Icon name="search" :size="24"/><input v-model="query" aria-label="搜索歌曲" placeholder="搜索歌曲、歌手、专辑" maxlength="200"/><button class="primary" :disabled="searching">{{searching?'搜索中…':'搜索'}}</button></form><div v-if="searched" class="section-heading"><h2>搜索结果 <small>{{results.length}}</small></h2><span class="muted">匿名曲库 · 可用性以曲目状态为准</span></div><template v-if="!searched"><div class="section-heading"><h2>先听听这些</h2><span class="muted">真实曲库 · 部分仅能试听</span></div><p v-if="discovering&&!discovery.length" class="muted" role="status">正在载入曲库…</p><p v-if="discoveryError" class="notice error" role="alert">{{discoveryError}} <button @click="discover">重试</button></p><TrackRows :tracks="discovery" @play="play(discovery,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></template><TrackRows v-else :tracks="results" @play="play(results,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/><div v-if="searched&&!results.length" class="empty-state"><span class="empty-symbol"><Icon name="search" :size="36"/></span><h2>{{searched?'试试另一种关键词。':'从一首喜欢的歌开始。'}}</h2><p>{{searched?'没有找到匹配的歌曲。':'发现、聆听、收藏到自己的音乐空间。'}}</p></div></template>
 <template v-else-if="page==='play'"><section class="page-heading compact"><span class="eyebrow">NOW PLAYING / 正在播放</span><h1>{{now?.title || '给此刻，选一首歌。'}}</h1><p class="lead">把节奏留给自己。</p></section><section class="now-playing"><div class="now-cover"><img :src="artworkURL(now?.picture)" alt="专辑封面"/><div class="now-cover-shadow"/></div><div class="now-information"><span class="eyebrow">{{p.state.resolutionStatus==='preview'?'PREVIEW / 当前仅可试听':'YOUR OWN RHYTHM'}}</span><h2>{{now?.title || '还没有选择歌曲'}}</h2><p>{{now?.artist || '去发现下一首喜欢的歌。'}}</p><small>{{now?.album}}</small><div class="large-controls"><button class="icon-button" aria-label="上一首" :disabled="!now" @click="p.previous()"><Icon name="previous" :size="26"/></button><button class="play-button" :aria-label="p.state.playing?'暂停':'播放'" :disabled="!now" @click="p.toggle()"><Icon :name="p.state.playing?'pause':'play'" :size="26"/></button><button class="icon-button" aria-label="下一首" :disabled="!now" @click="p.next()"><Icon name="next" :size="26"/></button><button class="icon-button" :class="{liked:now&&music.likedIDs.has(now.id)}" aria-label="喜欢当前歌曲" :disabled="!now" @click="now&&music.toggleLike(now)"><Icon name="heart" :size="24"/></button></div><div class="button-row"><button class="subtle" :disabled="!now" @click="overlay.lyrics=true"><Icon name="lyrics" :size="18"/>打开歌词</button><button class="subtle" :disabled="!now" @click="now&&overlay.add(now)"><Icon name="plus" :size="18"/>加入歌单</button><a class="subtle" href="/play" target="_blank" rel="noopener noreferrer">独立窗口 ↗</a></div><p class="fine-print">持续聆听建议保留播放器页。锁屏与后台播放取决于浏览器和系统。</p></div></section><div class="section-heading"><h2>接下来播放 <small>{{Math.max(0,p.state.tracks.length-p.state.currentIndex-1)}}</small></h2><RouterLink to="/queue">查看队列 →</RouterLink></div><TrackRows :tracks="p.state.tracks.slice(p.state.currentIndex+1,p.state.currentIndex+4)" @play="p.playAt(p.state.currentIndex+1+$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></template>
 <template v-else-if="page==='queue'||page==='likes'||page==='history'"><section class="page-heading"><span class="eyebrow">{{page==='queue'?'UP NEXT / 当前设备':page==='likes'?'YOUR FAVORITES / 喜欢的歌':'RECENTLY PLAYED / 最近播放'}}</span><h1>{{heading}}</h1><p class="lead">{{page==='queue'?'待播顺序和位置自动保存。刷新后，点击播放继续。':page==='likes'?'那些让你按下爱心的瞬间。':'每一次聆听，都有迹可循。'}}</p></section><div class="section-heading"><h2>{{page==='queue'?'待播队列':page==='likes'?'喜欢的歌':'最近播放'}} <small>{{page==='queue'?p.state.tracks.length:page==='likes'?music.likes.length:music.history.length}}</small></h2><div class="button-row"><template v-if="page==='queue'"><button class="subtle" @click="p.reloadQueue()">恢复服务器队列</button><button class="subtle" @click="p.clear()">清空队列</button></template><button v-if="page==='history'" class="subtle" @click="music.clearHistory()">清空历史</button><button v-if="page==='likes'&&music.likes.length" class="primary small" @click="play(music.likes)"><Icon name="play" :size="15"/>播放全部</button></div></div><TrackRows v-if="page==='queue'" :tracks="p.state.tracks" editable queue @play="p.playAt($event)" @remove="p.removeAt($event)" @move="(from,to)=>p.move(from,to)" @add="overlay.add" @share="overlay.share('track',$event.id)"/><TrackRows v-else :tracks="page==='likes'?music.likes:historyTracks" @play="play(page==='likes'?music.likes:historyTracks,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/><div v-if="!(page==='queue'?p.state.tracks.length:page==='likes'?music.likes.length:music.history.length)" class="empty-state"><span class="empty-symbol"><Icon :name="page==='queue'?'queue':page==='likes'?'heart':'history'" :size="36"/></span><h2>{{page==='queue'?'留一点期待给下一首。':page==='likes'?'遇见喜欢，记得留个爱心。':'音乐会在这里留下足迹。'}}</h2><RouterLink to="/search">去发现歌曲 →</RouterLink></div></template>
 <template v-else-if="page==='shares'"><section class="page-heading"><span class="eyebrow">SHARED BY YOU / 分享管理</span><h1>分享喜欢，保留选择。</h1><p class="lead">分享链接只读，30 天后过期。撤销之后，原链接立即失效。</p></section><div v-for="share in music.shares" :key="share.id" class="share-row"><span class="share-icon"><Icon name="share"/></span><div><strong>{{shareName(share.targetID)}}</strong><small>{{share.kind==='playlist'?'歌单':'单曲'}} · {{share.revoked?'已撤销':'只读链接'}}</small></div><button class="subtle" :disabled="share.revoked" @click="music.revoke(share.id)">{{share.revoked?'已撤销':'撤销分享'}}</button></div><div v-if="!music.shares.length" class="empty-state"><Icon name="share" :size="40"/><h2>把好音乐分享给朋友。</h2><p>从歌曲或歌单创建分享链接。</p></div></template>
 <template v-else-if="selected"><button class="back-link" @click="music.selectedID=''"><Icon name="arrow" :size="17"/>我的音乐</button><section class="playlist-header"><img :src="artworkURL(selected.tracks[0]?.picture)" alt="歌单封面"/><div><span class="eyebrow">YOUR PRIVATE PLAYLIST / 自有歌单</span><h1>{{selected.name}}</h1><p class="lead">{{selected.tracks.length}} 首歌曲 · 私有收藏</p><div class="button-row"><button class="primary" :disabled="!selected.tracks.length" @click="play(selected.tracks)"><Icon name="play" :size="17"/>播放歌单</button><button class="subtle" @click="rename"><Icon name="edit" :size="16"/>重命名</button><button class="subtle" @click="overlay.share('playlist',selected.id)"><Icon name="share" :size="16"/>只读分享</button><button class="icon-button" aria-label="删除歌单" @click="deletePlaylist"><Icon name="trash" :size="18"/></button></div></div></section><TrackRows :tracks="selected.tracks" editable @play="play(selected!.tracks,$event)" @move="reorder" @remove="removeTrack" @add="overlay.add" @share="overlay.share('track',$event.id)"/><div v-if="!selected.tracks.length" class="empty-state"><Icon name="music" :size="38"/><h2>给这张歌单，添一点旋律。</h2><RouterLink to="/search">搜索歌曲 →</RouterLink></div></template>
 <template v-else><section class="library-hero"><div><span class="eyebrow">YOUR MUSIC. YOUR SPACE.</span><h1>生活有很多节奏，<br/>这一刻，听自己的。</h1><p>自己的歌单，自己的喜欢。<br/>不需要网易云账号，打开就能聆听。</p><RouterLink class="primary" to="/search">发现下一首 <Icon name="arrow" :size="18"/></RouterLink></div><div class="hero-art" aria-hidden="true"><div class="record-sleeve"><span>THE PERSONAL COLLECTION</span><div class="record"><div>BetaGo<small>SIDE A / 33⅓</small></div></div><i>PLAY SOMETHING YOU LOVE.</i></div></div></section><section class="library-summary"><RouterLink to="/likes"><strong>{{music.likes.length.toString().padStart(2,'0')}}</strong><span>首喜欢</span></RouterLink><span class="summary-divider"/><button @click="scrollCollection()"><strong>{{music.playlists.length.toString().padStart(2,'0')}}</strong><span>张歌单</span></button><span class="summary-divider"/><RouterLink to="/history"><strong>{{music.history.length.toString().padStart(2,'0')}}</strong><span>首最近播放</span></RouterLink><span class="library-caption">COLLECT THE MOMENTS.</span></section><section class="library-discovery"><div class="section-heading"><h2>先听一首</h2><RouterLink to="/search">搜索更多歌曲 →</RouterLink></div><p class="muted">真实匿名曲库，点击歌曲即可试播。部分歌曲仅可试听或暂不可用，播放器会明确提示。</p><p v-if="discovering&&!discovery.length" class="muted" role="status">正在载入曲库…</p><p v-if="discoveryError" class="notice error" role="alert">{{discoveryError}} <button @click="discover">重试</button></p><TrackRows :tracks="discovery.slice(0,4)" @play="play(discovery,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></section><section id="collection"><div class="section-heading"><h2>我的歌单 <small>{{music.playlists.length}}</small></h2><button class="subtle" @click="overlay.create()"><Icon name="plus" :size="17"/>新建歌单</button></div><div class="playlist-grid"><button v-for="(playlist,index) in music.playlists" :key="playlist.id" class="playlist-card" @click="choose(playlist.id)"><div class="playlist-art" :class="`cover-${index%4}`"><img :src="artworkURL(playlist.tracks[0]?.picture)" alt="" loading="lazy"/><span class="playlist-card-play"><Icon name="play" :size="22"/></span></div><strong>{{playlist.name}}</strong><span>{{playlist.tracks.length}} 首 · 私有歌单</span></button><button class="new-playlist-card" @click="overlay.create()"><span><Icon name="plus" :size="28"/></span><strong>{{music.playlists.length?'再留一个位置。':'创建你的第一张歌单'}}</strong><small>为某段心情，留一张歌单。</small></button></div></section><section v-if="music.likes.length" class="library-favorites"><div class="section-heading"><h2>喜欢的歌</h2><RouterLink to="/likes">查看全部 →</RouterLink></div><TrackRows :tracks="music.likes.slice(0,4)" @play="play(music.likes,$event)" @add="overlay.add" @share="overlay.share('track',$event.id)"/></section></template>
</template>
